import 'package:flutter/material.dart';
import '../../data/repositories/promotion_repository.dart';
class PromotionFormScreen extends StatefulWidget { const PromotionFormScreen({required this.repository, this.promotionId, super.key}); final PromotionRepository repository; final String? promotionId; @override State<PromotionFormScreen> createState()=>_PromotionFormScreenState(); }
class _PromotionFormScreenState extends State<PromotionFormScreen>{ final _f=GlobalKey<FormState>(); final _name=TextEditingController(); final _desc=TextEditingController(); final _type=TextEditingController(text:'quantity_discount'); final _priority=TextEditingController(text:'0'); final _minQty=TextEditingController(); final _discType=TextEditingController(text:'percentage'); final _discValue=TextEditingController(text:'0'); bool _stack=false; bool _active=true; bool _saving=false;
  Future<void> _save() async { if(!_f.currentState!.validate())return; setState(()=>_saving=true); final body={'name':_name.text.trim(),'description':_desc.text.trim(),'type':_type.text.trim(),'priority':int.tryParse(_priority.text)??0,'stackable':_stack,'isActive':_active,'minQuantity':double.tryParse(_minQty.text),'discountType':_discType.text.trim(),'discountValue':double.tryParse(_discValue.text)}..removeWhere((k,v)=>v==null||v==''); try{await widget.repository.save(body,id:widget.promotionId); if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Promoción guardada')));Navigator.pop(context,true);} } catch(e){ if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));} if(mounted)setState(()=>_saving=false);} 
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.promotionId==null?'Nueva promoción':'Editar promoción')),body:Form(key:_f,child:ListView(padding:const EdgeInsets.all(16),children:[TextFormField(controller:_name,decoration:const InputDecoration(labelText:'Nombre'),validator:(v)=>v==null||v.trim().isEmpty?'Requerido':null),TextFormField(controller:_desc,decoration:const InputDecoration(labelText:'Descripción')),TextFormField(controller:_type,decoration:const InputDecoration(labelText:'Tipo')),SwitchListTile(value:_active,onChanged:(v)=>setState(()=>_active=v),title:const Text('Activa')),SwitchListTile(value:_stack,onChanged:(v)=>setState(()=>_stack=v),title:const Text('Combinable')),TextFormField(controller:_priority,decoration:const InputDecoration(labelText:'Prioridad')),TextFormField(controller:_minQty,decoration:const InputDecoration(labelText:'Cantidad mínima')),TextFormField(controller:_discType,decoration:const InputDecoration(labelText:'Tipo descuento')),TextFormField(controller:_discValue,decoration:const InputDecoration(labelText:'Valor descuento')),const SizedBox(height:16),FilledButton(onPressed:_saving?null:_save,child:Text(_saving?'Guardando...':'Guardar'))])));
}
